/// <reference types="vite/client" />
import { expect, test } from "vitest";

/**
 * Proves no backend function can skip the permission checks: only
 * lib/functions.ts may use Convex's raw function builders, and auth.ts
 * (whose login endpoints are generated by Convex Auth).
 */
const sources = import.meta.glob("../**/*.ts", { query: "?raw", import: "default", eager: true }) as Record<
  string,
  string
>;

const RAW_BUILDERS = [
  "query",
  "mutation",
  "action",
  "internalQuery",
  "internalMutation",
  "internalAction",
  "httpAction",
];
const ALLOWED = new Set(["../lib/functions.ts"]);

function backendFiles() {
  return Object.entries(sources).filter(
    ([path]) => !path.includes("/_generated/") && !path.includes("/tests/"),
  );
}

test("the scan actually sees the backend files", () => {
  const paths = backendFiles().map(([path]) => path);
  expect(paths).toContain("../users.ts");
  expect(paths).toContain("../lib/functions.ts");
  expect(paths.length).toBeGreaterThan(10);
});

test("only lib/functions.ts imports raw query/mutation/action builders", () => {
  const offenders: string[] = [];
  for (const [path, source] of backendFiles()) {
    if (ALLOWED.has(path)) continue;
    const importRe = /import\s+(type\s+)?\{([^}]*)\}\s+from\s+["']([^"']+)["']/g;
    for (const match of source.matchAll(importRe)) {
      const [, typeOnly, names, from] = match;
      const fromServer = from.endsWith("_generated/server") || from === "convex/server";
      if (!fromServer || typeOnly) continue;
      for (const raw of names.split(",")) {
        const name = raw.trim().replace(/^type\s+/, "").split(/\s+as\s+/)[0];
        if (raw.trim().startsWith("type ")) continue;
        if (RAW_BUILDERS.includes(name) || /Generic$/.test(name)) offenders.push(`${path}: ${name}`);
      }
    }
  }
  expect(offenders).toEqual([]);
});

test("every exported Convex function is built from a permission wrapper", () => {
  const wrapperNames =
    /\b(viewerQuery|signedInQuery|signedInMutation|staffQuery|staffMutation|residentQuery|residentMutation|internalQuery|internalMutation|internalAction)\(/;
  const offenders: string[] = [];
  for (const [path, source] of backendFiles()) {
    if (ALLOWED.has(path) || path === "../auth.ts" || path.startsWith("../lib/")) continue;
    if (path === "../http.ts" || path === "../auth.config.ts" || path === "../schema.ts") continue;
    for (const match of source.matchAll(/export const (\w+)\s*=\s*([^;]*)/g)) {
      const [, name, rhs] = match;
      // Only look at exports that define functions (they're called with an object).
      if (!/^\w+\(\{/.test(rhs.trim())) continue;
      if (!wrapperNames.test(rhs)) offenders.push(`${path}: ${name}`);
    }
  }
  expect(offenders).toEqual([]);
});
